#include <stdio.h>
#define IS_FLOAT(e) _Generic((e), float: 1, default: 0)
#define IS_DOUBLE(e) _Generic((e), double: 1, default: 0)
int main(void)
{
    float f = 1.5F;
    int n = 2;
    double d = 0.25;
    _Static_assert(IS_FLOAT(f + f), "f + f has type float");
    _Static_assert(IS_FLOAT(f + n), "f + n has type float");
    _Static_assert(IS_DOUBLE(f + d), "f + d has type double");
    puts("f + f: float; f + n: float; f + d: double");
    return 0;
}
